document.addEventListener('keydown',e=>{
 if($('.modal')){if(e.key==='Escape'){e.preventDefault();closeModal()}else trapFocus(e,$('.modal'));return}
 if(menuOpen){if(e.key==='Escape'){e.preventDefault();setMenu(false)}else trapFocus(e,$('#sidebar'));return}
 if(e.key==='Escape'&&state.layerMenu){state.layerMenu=false;render();$('[data-action=layers]')?.focus();return}
 const tab=e.target.closest('[role=tab]');
 if(tab&&['ArrowLeft','ArrowRight','Home','End'].includes(e.key)){
  e.preventDefault();const keys=['3d','compare','finance','report'],i=keys.indexOf(state.tab);
  state.tab=keys[e.key==='Home'?0:e.key==='End'?3:(i+(e.key==='ArrowRight'?1:3))%4];render();$(`[data-tab="${state.tab}"]`).focus({preventScroll:true});return;
 }
 if(['INPUT','TEXTAREA','SELECT','CANVAS'].includes(e.target.tagName)||e.target.isContentEditable)return;
 if(e.target.closest('.prototype-switcher')&&['ArrowLeft','ArrowRight'].includes(e.key)){e.preventDefault();cycleVariant(e.key==='ArrowRight'?1:-1)}
 if((e.key==='Enter'||e.key===' ')&&e.target.dataset.mapLot){e.preventDefault();selectLot(e.target.dataset.mapLot)}
});

function searchLot(query){const q=query.trim().toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'');if(!q){notify('Digite Jardim Oceania, Bessa, Cabo Branco ou coordenadas.');return}
 const found=lots.find(l=>l.name.toLowerCase().includes(q)||l.id===q);
 if(found){selectLot(found.id);return}
 const pair=query.trim().split(/[;\s]+|,\s+(?=-?\d)/).map(Number).filter(Number.isFinite);
 if(pair.length===2){const [lat,lng]=pair;if(Math.abs(lat)>90||Math.abs(lng)>180){notify('Coordenadas inválidas. Use latitude e longitude WGS84.');return}if(lat<-7.3||lat>-7||lng<-35||lng>-34.75){modal('Fora do recorte demonstrativo.',`<p>Use um ponto próximo de João Pessoa. O protótipo não consulta cadastro oficial; as coordenadas são apenas uma entrada para confirmar o fluxo.</p>`,btn('Voltar','','close-modal','primary'));return}const near=lots.reduce((a,b)=>Math.hypot(a.lat-lat,a.lng-lng)<Math.hypot(b.lat-lat,b.lng-lng)?a:b);modal('Nenhum lote cadastral foi consultado.',`<p>Coordenadas recebidas: ${esc(query)}.</p><p>Como não há integração GIS nesta demonstração, você pode explorar o exemplo de ${near.name}, importar um GeoJSON ou desenhar um perímetro.</p>`,btn('Voltar','','close-modal')+`<button class="btn primary" id="use-example">Explorar exemplo ${icon('arrowRight')}</button>`);$('#use-example').onclick=()=>{closeModal();selectLot(near.id)};return}
 modal('Vamos confirmar esse terreno.',`<p>O endereço “${esc(query)}” não faz parte dos exemplos desta demonstração.</p><p>Experimente <strong>Jardim Oceania</strong>, <strong>Bessa</strong> ou <strong>Cabo Branco</strong>. Para um novo terreno, importe um polígono GeoJSON ou desenhe o perímetro no mapa esquemático.</p>`,btn('Entendi','','close-modal','primary'));
}
function polygonArea(points){let a=0;for(let i=0;i<points.length;i++){const [x,y]=points[i],[x2,y2]=points[(i+1)%points.length];a+=x*y2-x2*y}return Math.abs(a)/2}
function selfIntersects(p){const cross=(a,b,c)=>(b[0]-a[0])*(c[1]-a[1])-(b[1]-a[1])*(c[0]-a[0]);for(let i=0;i<p.length;i++)for(let j=i+1;j<p.length;j++){if(j===i+1||i===0&&j===p.length-1)continue;const a=p[i],b=p[(i+1)%p.length],c=p[j],d=p[(j+1)%p.length];if(cross(a,b,c)*cross(a,b,d)<0&&cross(c,d,a)*cross(c,d,b)<0)return true}return false}
function finishDrawing(){if(state.drawPoints.length<3){notify('Marque pelo menos três vértices no mapa.');return}if(selfIntersects(state.drawPoints)){notify('O perímetro cruza a si mesmo. Cancele e desenhe novamente.');return}const a=polygonArea(state.drawPoints);if(a<50){notify('O perímetro ficou muito pequeno. Desenhe uma área maior.');return}const pts=[...state.drawPoints];const area=Math.round(a*.36);state.lot={id:'D01',name:'Terreno desenhado',address:'Perímetro manual · mapa esquemático',area,width:Math.round(Math.sqrt(area*.75)),depth:Math.round(Math.sqrt(area/.75)),lat:-7.0816,lng:-34.8368,zone:'Não identificado',coastal:false,custom:true,position:[pts.reduce((s,p)=>s+p[0],0)/pts.length,pts.reduce((s,p)=>s+p[1],0)/pts.length]};state.customPolygon=pts;state.drawing=false;state.drawPoints=[];render();notify('Perímetro criado. Área aproximada em escala fictícia.');}
$('#geojson-input').addEventListener('change',async e=>{const file=e.target.files[0];e.target.value='';if(!file)return;if(file.size>2e6){notify('Use um GeoJSON com até 2 MB para esta demonstração.');return}try{
 const data=JSON.parse(await file.text());const geom=data.type==='FeatureCollection'?(data.features?.length===1?data.features[0].geometry:null):data.type==='Feature'?data.geometry:data;
 if(!geom||geom.type!=='Polygon'||geom.coordinates.length!==1)throw Error('Importe um único Polygon sem furos, em coordenadas WGS84.');
 const ring=geom.coordinates[0];if(!Array.isArray(ring)||ring.length<4)throw Error('O polígono precisa de pelo menos três vértices e um anel fechado.');
 if(ring.some(p=>!Array.isArray(p)||p.length<2||!Number.isFinite(p[0])||!Number.isFinite(p[1])||Math.abs(p[0])>180||Math.abs(p[1])>90))throw Error('Coordenadas inválidas. Use [longitude, latitude] em WGS84.');
 if(ring[0][0]!==ring.at(-1)[0]||ring[0][1]!==ring.at(-1)[1])throw Error('O primeiro e o último vértice do anel devem coincidir.');
 const pts=ring.slice(0,-1),lng=pts.reduce((s,p)=>s+p[0],0)/pts.length,lat=pts.reduce((s,p)=>s+p[1],0)/pts.length;
 if(lat<-7.3||lat>-7||lng<-35||lng>-34.75)throw Error('O polígono deve estar no recorte demonstrativo de João Pessoa.');
 const projected=pts.map(([x,y])=>[(x-lng)*111320*Math.cos(lat*Math.PI/180),(y-lat)*111320]);if(selfIntersects(projected))throw Error('A geometria possui auto-interseção. Revise os vértices.');
 const area=Math.round(polygonArea(projected));if(area<50||area>100000)throw Error('Use um terreno entre 50 e 100.000 m² neste protótipo.');
 const xs=projected.map(p=>p[0]),ys=projected.map(p=>p[1]),w=Math.max(...xs)-Math.min(...xs),d=Math.max(...ys)-Math.min(...ys),scale=Math.min(150/w,150/d);
 state.lot={id:'I01',name:'Terreno importado',address:file.name,area,width:Math.round(w),depth:Math.round(d),lat,lng,zone:'Não identificado',coastal:false,custom:true,position:[386,245]};state.customPolygon=projected.map(([x,y])=>[386+x*scale,245-y*scale]);state.step=1;state.page='analysis';render();modal('Perímetro importado.',`<p>${esc(file.name)} · ${number(area)} m² aproximados.</p><p>A área foi estimada por uma projeção local simplificada. O desenho é centralizado no mapa esquemático e não corresponde à sua posição cadastral.</p><div class="notice">${icon('info')}Não foram consultadas interseções com zoneamento, restrições ou malha oficial. Os índices da análise continuam demonstrativos.</div>`,btn('Explorar terreno','arrowRight','close-modal','primary'));
 }catch(err){modal('Não foi possível importar.',`<p>${esc(err.message)}</p><p>Formato aceito: GeoJSON Polygon ou Feature com Polygon, um anel fechado, sem furos, coordenadas [longitude, latitude].</p>`,btn('Entendi','','close-modal','primary'))}});
function downloadSnapshot(){const c=calc();const data={schema:'URBA_PROTOTYPE_0.1',status:'PRELIMINAR',demonstration:true,generated_at:new Date().toISOString(),parcel:{...state.lot,geometry_note:'Synthetic or approximate. No cadastral verification.'},assumptions:{floors:state.floors,requested_occupancy_percent:state.to,efficiency_percent:state.efficiency,unit_area_m2:state.unitArea,use:state.use,flat_terrain:true,base_ca:2,max_ca:3,legal_rules_validated:false,price_per_sellable_m2:state.price,cost_per_built_m2:state.cost,indirect_percent:state.indirect,target_profit_percent:state.profit,land_price:state.landPrice},results:c,dependencies:{official_geometry:'PENDING',zoning:'PENDING',rule_set_hash:null,legal_review:'PENDING',coastal_regime:state.lot.coastal?'BLOCKED':'NOT_ASSESSED',topography:'PENDING'},exclusions:['outorga','monthly_cashflow','tax_detail','bank_eligibility','architectural_project']};const blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'});const u=URL.createObjectURL(blob),a=document.createElement('a');a.href=u;a.download=`urba-cenario-${state.lot.id}-preliminar.json`;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);notify('Snapshot demonstrativo exportado em JSON.');}

// Renderer geométrico sem dependências: projeção de pontos 3D e ordenação das faces por profundidade.
let canvases=[],resizeObserver;
function setupCanvases(){if(resizeObserver)resizeObserver.disconnect();canvases=$$('[data-canvas]');resizeObserver=new ResizeObserver(()=>drawAll());for(const canvas of canvases){resizeObserver.observe(canvas);if(['decor','report'].includes(canvas.dataset.canvas))continue;
 canvas.tabIndex=0;if(canvas.dataset.canvas==='preview')canvas.setAttribute('aria-label',`Prévia: ${modelDescription()}. Use as setas para girar e os botões de mais e menos do teclado para ampliar.`);
 let drag=null;canvas.addEventListener('pointerdown',e=>{if(e.button!==0||(e.pointerType==='touch'&&!state.interactiveTouch))return;canvas.focus({preventScroll:true});drag={x:e.clientX,y:e.clientY,rotation:state.rotation,elevation:state.elevation};canvas.setPointerCapture(e.pointerId)});canvas.addEventListener('pointermove',e=>{if(!drag)return;state.rotation=drag.rotation+(e.clientX-drag.x)*.009;state.elevation=Math.max(.23,Math.min(1.5,drag.elevation+(e.clientY-drag.y)*.005));drawAll()});canvas.addEventListener('pointerup',()=>drag=null);canvas.addEventListener('pointercancel',()=>drag=null);canvas.addEventListener('wheel',e=>{if(document.activeElement!==canvas&&!e.ctrlKey)return;e.preventDefault();state.zoom=Math.max(.5,Math.min(1.7,state.zoom-e.deltaY*.001));drawAll()},{passive:false});canvas.addEventListener('keydown',e=>{if(['ArrowLeft','ArrowRight','ArrowUp','ArrowDown','+','-'].includes(e.key)){e.preventDefault();if(e.key==='ArrowLeft')state.rotation-=.12;if(e.key==='ArrowRight')state.rotation+=.12;if(e.key==='ArrowUp')state.elevation=Math.min(1.5,state.elevation+.1);if(e.key==='ArrowDown')state.elevation=Math.max(.23,state.elevation-.1);if(e.key==='+')state.zoom=Math.min(1.7,state.zoom+.1);if(e.key==='-')state.zoom=Math.max(.5,state.zoom-.1);drawAll()}})
 }drawAll();requestAnimationFrame(drawAll)}
function drawAll(){$$('[data-action="view-top"]').forEach(b=>{b.setAttribute('aria-pressed',state.elevation>1.3);b.classList.toggle('active',state.elevation>1.3)});if($('#model-description'))$('#model-description').textContent=modelDescription();for(const c of canvases)drawScene(c);$$('.wind-rose g').forEach(g=>g.setAttribute('transform',`translate(35 35) rotate(${state.rotation*180/Math.PI})`))}
function drawScene(canvas){
 const rect=canvas.getBoundingClientRect();if(!rect.width||!rect.height)return;const dpr=Math.min(devicePixelRatio||1,2);if(canvas.width!==Math.round(rect.width*dpr)||canvas.height!==Math.round(rect.height*dpr)){canvas.width=Math.round(rect.width*dpr);canvas.height=Math.round(rect.height*dpr)}const ctx=canvas.getContext('2d');ctx.setTransform(dpr,0,0,dpr,0,0);const W=rect.width,H=rect.height;ctx.clearRect(0,0,W,H);
 const decor=canvas.dataset.canvas==='decor',report=canvas.dataset.canvas==='report';const c=calc(),lotW=state.lot.width,lotD=state.lot.depth;const scale=Math.min(W/(lotW*1.7),H/(lotD*.65+c.height*1.5))*state.zoom*(decor?.82:.91),angle=state.rotation,el=state.elevation;
 const origin=[W*.5,H*(decor?.64:.66)];
 const raw=(x,y,z)=>{const rx=x*Math.cos(angle)-y*Math.sin(angle),ry=x*Math.sin(angle)+y*Math.cos(angle);return [origin[0]+rx*scale,origin[1]+(ry*Math.sin(el)-z*Math.cos(el))*scale,ry*Math.cos(el)+z*Math.sin(el)]};
 const polygon=(points,fill,stroke='#ffffff44',line=1,dash=[])=>{ctx.beginPath();points.forEach((p,i)=>{const [x,y]=raw(...p);i?ctx.lineTo(x,y):ctx.moveTo(x,y)});ctx.closePath();if(fill){ctx.fillStyle=fill;ctx.fill()}if(stroke){ctx.strokeStyle=stroke;ctx.lineWidth=line;ctx.setLineDash(dash);ctx.stroke();ctx.setLineDash([])}};
 const line=(a,b,color,width=1,dash=[])=>{const p=raw(...a),q=raw(...b);ctx.beginPath();ctx.moveTo(p[0],p[1]);ctx.lineTo(q[0],q[1]);ctx.strokeStyle=color;ctx.lineWidth=width;ctx.setLineDash(dash);ctx.stroke();ctx.setLineDash([])};
 const ground=Math.max(lotW,lotD)*.85;
 if(!decor){for(let i=-ground;i<=ground;i+=5){line([i,-ground,-.25],[i,ground,-.25],'#dce4d34d',.6);line([-ground,i,-.25],[ground,i,-.25],'#dce4d34d',.6)}
 polygon([[-lotW/2-6,-lotD/2-6,-.15],[lotW/2+6,-lotD/2-6,-.15],[lotW/2+6,lotD/2+6,-.15],[-lotW/2-6,lotD/2+6,-.15]],'#e6eadd',null);
 polygon([[-lotW/2-5,lotD/2+1,0],[lotW/2+5,lotD/2+1,0],[lotW/2+5,lotD/2+5,0],[-lotW/2-5,lotD/2+5,0]],'#d6ddcd',null);
 }
 const corners=[[-lotW/2,-lotD/2,0],[lotW/2,-lotD/2,0],[lotW/2,lotD/2,0],[-lotW/2,lotD/2,0]];
 polygon(corners,'#d6e4bd','#8ca76a',1,[4,3]);
 const bw=Math.max(1,Math.sqrt(c.footprint*(lotW/lotD))),bd=c.footprint/bw,building=[[-bw/2,-bd/2],[bw/2,-bd/2],[bw/2,bd/2],[-bw/2,bd/2]];
 if(state.setbacks&&!decor){const inset=[[-lotW/2+3,-lotD/2+5,0],[lotW/2-3,-lotD/2+5,0],[lotW/2-3,lotD/2-5,0],[-lotW/2+3,lotD/2-5,0]];polygon(inset,'#c3d6a38a','#91ab70',.8,[3,4])}
 // Ombre projetée, indicative sans calcul solaire.
 polygon(building.map(([x,y])=>[x+7,y+5,0]),'#5a744222',null);
 const floorH=3,faces=[];
 for(let floor=0;floor<state.floors;floor++){
  const z0=floor*floorH+.2,z1=(floor+1)*floorH,shrink=1;
  const p=building.map(([x,y])=>[x*shrink,y*shrink]);
  for(let side=0;side<4;side++){const p1=p[side],p2=p[(side+1)%4],pts=[[...p1,z0],[...p2,z0],[...p2,z1],[...p1,z1]];const dep=pts.reduce((s,v)=>s+raw(...v)[2],0)/4;faces.push({pts,depth:dep,color:['#85aa78','#517d62','#5e8e6c','#a2bc89'][side],floor,side,p1,p2,z0,z1})}
  if(floor===state.floors-1)faces.push({pts:p.map(v=>[...v,z1]),depth:100000,color:'#cbd9b9',roof:true});
 }
 faces.sort((a,b)=>a.depth-b.depth);
 for(const f of faces){polygon(f.pts,f.color,'#eff4e28a',.6);if(f.roof){const z=state.floors*3;polygon([[-bw*.34,-bd*.34,z+.15],[bw*.34,-bd*.34,z+.15],[bw*.34,bd*.34,z+.15],[-bw*.34,bd*.34,z+.15]],'#bbcca6','#8da77a55',.7);continue}
  // Façades, garde-corps et baies schématiques.
  const x1=f.p1[0],y1=f.p1[1],x2=f.p2[0],y2=f.p2[1];
  const glazing=[[x1+(x2-x1)*.09,y1+(y2-y1)*.09,f.z0+.5],[x1+(x2-x1)*.91,y1+(y2-y1)*.91,f.z0+.5],[x1+(x2-x1)*.91,y1+(y2-y1)*.91,f.z1-.4],[x1+(x2-x1)*.09,y1+(y2-y1)*.09,f.z1-.4]];
  polygon(glazing,f.floor===0&&state.use==='Misto'?'#b6c5ac':'#d4e4d242',null);
  for(let j=1;j<5;j++){const t=j/5,x=x1+(x2-x1)*t,y=y1+(y2-y1)*t;line([x,y,f.z0+.4],[x,y,f.z1-.4],'#ecf4db77',.7)}
  line([x1,y1,f.z1-.4],[x2,y2,f.z1-.4],'#dfebcd',1);
 }
 if(state.envelope&&!decor){const eh=24;for(let i=0;i<4;i++){const p=corners[i],q=corners[(i+1)%4];line([p[0]*.83,p[1]*.8,0],[p[0]*.83,p[1]*.8,eh],'#809f5970',.8,[3,4]);line([p[0]*.83,p[1]*.8,eh],[q[0]*.83,q[1]*.8,eh],'#809f5980',.8,[3,4])}}
 if(!decor){
 const label=(text,x,y,z,color='#8ca475',size=9)=>{const p=raw(x,y,z);ctx.font=`${size}px "DM Sans",sans-serif`;ctx.textAlign='center';ctx.fillStyle=color;ctx.fillText(text,p[0],p[1])};
 label(`${number(lotW)} m`,0,lotD/2+4,0,'#879d72',8);label(`${number(lotD)} m`,-lotW/2-4,0,0,'#879d72',8);
 const hp=raw(bw/2+2,bd/2,c.height/2);ctx.font='9px "DM Sans",sans-serif';ctx.fillStyle='#759565';ctx.fillText(`${c.height} m`,hp[0]+9,hp[1]);
 label('FRENTE DO LOTE',0,lotD/2+9,0,'#9ba88d',7);
 // Norte da cena e escala são referenciais, não uma georreferência homologada.
 const a=raw(-lotW/2-7,-lotD/2,0),b=raw(-lotW/2-7,-lotD/2-7,0);ctx.beginPath();ctx.moveTo(a[0],a[1]);ctx.lineTo(b[0],b[1]);ctx.strokeStyle='#6f9054';ctx.lineWidth=1.2;ctx.stroke();ctx.fillStyle='#6f9054';ctx.font='8px sans-serif';ctx.fillText('N',b[0],b[1]-5);
 }
}
window.addEventListener('resize',()=>requestAnimationFrame(drawAll));
window.addEventListener('popstate',()=>{const v=new URLSearchParams(location.search).get('variant');if(variants[v]){state.variant=v;state.step=v==='A'?1:3;state.tab='3d';render()}});

const mobileQuery=window.matchMedia('(max-width:1024px)');
let menuOpen=false;
function focusMain(scroll=true){const h=$('main h1');if(h){h.tabIndex=-1;h.focus({preventScroll:true})}else $('#main-content').focus({preventScroll:true});if(scroll)$('#main-content').scrollTo({top:0,behavior:'instant'})}
function rememberControl(el){if(!el||!el.closest('#main-content'))return null;if(el.id)return '#'+CSS.escape(el.id);for(const key of ['action','use','layer','report','tab','scenario'])if(el.dataset[key])return `[data-${key}="${CSS.escape(el.dataset[key])}"]`;return null}
function trapFocus(e,root){if(e.key!=='Tab')return;const items=[...root.querySelectorAll('button:not(:disabled),a[href],input:not(:disabled),select,textarea,[tabindex="0"]')].filter(x=>x.getClientRects().length&&!x.closest('[inert]'));const first=items[0],last=items.at(-1);if(!first)return;if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}
function syncAccess(){const hasModal=!!$('.modal');$('#app').inert=hasModal;$('.main-shell').inert=menuOpen;$('#sidebar').inert=mobileQuery.matches&&!menuOpen;$('.prototype-switcher').inert=hasModal||menuOpen;$('.skip-link').inert=hasModal||menuOpen;$('#menu-backdrop').hidden=!menuOpen;$('#menu-backdrop').inert=hasModal;document.body.style.overflow=hasModal||menuOpen?'hidden':'';}
function setMenu(open,restore=true){menuOpen=Boolean(open&&mobileQuery.matches);$('#sidebar').classList.toggle('mobile-open',menuOpen);$('#mobile-menu').setAttribute('aria-expanded',menuOpen);if(menuOpen){$('#sidebar').setAttribute('role','dialog');$('#sidebar').setAttribute('aria-modal','true');$('#sidebar').setAttribute('aria-label','Menu de navegação')}else{for(const a of ['role','aria-modal','aria-label'])$('#sidebar').removeAttribute(a)}syncAccess();if(menuOpen)$('#drawer-close').focus();else if(restore&&mobileQuery.matches)$('#mobile-menu').focus()}
mobileQuery.addEventListener('change',()=>setMenu(false,false));
function chooseLayout(){const descriptions={A:'Localize o lote e consulte o diagnóstico.',B:'Explore o volume com os controles ao lado.',C:'Veja o estudo em uma visão executiva.'};modal('Como você prefere explorar?',`<p>Três formas de ver o mesmo estudo. O terreno e as premissas são mantidos ao alternar.</p><div class="layout-choices">${Object.entries(variants).map(([key,label],i)=>`<button class="layout-choice ${state.variant===key?'active':''}" data-layout="${key}" aria-pressed="${state.variant===key}">${icon(['layers','cube','file'][i])}<span><strong>${label}</strong><small>${descriptions[key]}</small></span>${state.variant===key?status('ATUAL','confirmed'):''}</button>`).join('')}</div>`)}
document.addEventListener('click',e=>{const b=e.target.closest('[data-layout]');if(b){const v=b.dataset.layout;closeModal();setVariant(v);focusMain()}});
function modelDescription(){const c=calc();return `${state.floors} pavimentos · ${number(c.height)} m de altura · ${number(c.gross)} m² computáveis · ${c.units} unidades estimadas de ${state.unitArea} m².`}
function updateRangeLabels(){for(const el of $$('input[data-control]'))el.setAttribute('aria-valuetext',el.dataset.control==='floors'?`${el.value} pavimentos`:el.dataset.control==='to'?`${el.value} por cento`:`${el.value} metros quadrados`)}
function announceResults(){clearTimeout(announceResults.timer);announceResults.timer=setTimeout(()=>$('#results-announcement').textContent=modelDescription(),450)}
function updateTableHints(){$$('.table-scroll').forEach(el=>{const hint=el.previousElementSibling;if(hint?.classList.contains('table-hint'))hint.hidden=el.scrollWidth<=el.clientWidth+1})}
function enhanceAccessibility(){
 $('#main-content').setAttribute('aria-busy','false');
 document.title=($('main h1')?.textContent||'Inteligência urbanística')+' | URBA';
 $$('.report-map [data-map-lot]').forEach(el=>{el.removeAttribute('data-map-lot');el.removeAttribute('role');el.removeAttribute('tabindex');el.removeAttribute('aria-label')});
 $('.report-map .map-svg')?.setAttribute('aria-label','Mapa esquemático do terreno selecionado para o relatório.');
 $$('#sidebar [data-page]').forEach(b=>{if(b.dataset.page===state.page)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current');b.title=b.textContent.trim()});
 $$('[data-step]').forEach(b=>{if(Number(b.dataset.step)===state.step)b.setAttribute('aria-current','step');else b.removeAttribute('aria-current')});
 $$('[data-use]').forEach(b=>b.setAttribute('aria-pressed',b.dataset.use===state.use));updateRangeLabels();
 $$('table').forEach((table,i)=>{
  const title=table.closest('.panel')?.querySelector('h3')?.textContent||'Comparação de cenários';table.setAttribute('aria-label',title);
  table.querySelectorAll('thead th').forEach(th=>th.scope='col');
  if(table.classList.contains('compare-table')||table.classList.contains('sensitivity-table'))table.querySelectorAll('tbody tr').forEach(tr=>{const first=tr.firstElementChild;if(first.tagName==='TD'){const th=document.createElement('th');th.textContent=first.textContent;first.replaceWith(th)}tr.firstElementChild.scope='row'});
  if(!table.parentElement.classList.contains('table-scroll')){const holder=document.createElement('div');holder.className='table-scroll';holder.tabIndex=0;holder.setAttribute('role','region');holder.setAttribute('aria-label',title+'. Tabela com rolagem horizontal.');const hint=document.createElement('p');hint.className='table-hint';hint.id=`table-hint-${i}`;hint.textContent='Deslize a tabela ou use as setas com ela em foco para ver todas as colunas.';holder.setAttribute('aria-describedby',hint.id);table.before(hint,holder);holder.append(table);if(holder.parentElement.style.overflow==='auto')holder.parentElement.style.overflow='hidden';}
 });requestAnimationFrame(updateTableHints);
}
window.addEventListener('resize',updateTableHints);

render();
